// Regenerate the client ABIs from the pinned contracts' artifacts, built with
// forge in lib/protocol and lib/account-keys: npm run abi. The artifacts own
// these ABIs and the generated files are tracked, so an ordinary build needs
// neither; `--check` says whether they still match the pins, writing nothing.
import { readFileSync, writeFileSync } from 'node:fs'
import { artifactPath } from './contract-artifacts.mjs'

const check = process.argv.includes('--check')
let stale = 0
for (const [contract, name] of [['Board', 'board'], ['ListRegistry', 'registry'], ['AccountKeys', 'accountKeys']]) {
  const path = artifactPath(contract)
  let artifact
  try {
    artifact = JSON.parse(readFileSync(new URL(`../${path}`, import.meta.url), 'utf8'))
  } catch {
    throw new Error(`${path} is missing: run forge build in lib/protocol and lib/account-keys first`)
  }
  const out = `// Generated by scripts/abi.mjs from ${path} — do not edit.
export const ${name}Abi = ${JSON.stringify(artifact.abi, null, 2)} as const
`
  const target = new URL(`../src/lib/abi/${name}.ts`, import.meta.url)
  if (check) {
    if (readFileSync(target, 'utf8') !== out) {
      stale++
      console.error(`src/lib/abi/${name}.ts differs from ${path}: run npm run abi`)
    }
  } else {
    writeFileSync(target, out)
    console.log(`wrote src/lib/abi/${name}.ts (${artifact.abi.length} entries)`)
  }
}
if (stale) process.exit(1)
if (check) console.log('the tracked ABIs match the pinned contracts')
